-- State transitions declared for UploadSession (shadow: an undeclared move raises a WARNING).
-- Generated by metaphor-schema

CREATE OR REPLACE FUNCTION bucket.upload_sessions_status_transition_check() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
    IF NEW."status" IS DISTINCT FROM OLD."status" AND NOT (
           (COALESCE(OLD."status"::text, ''), COALESCE(NEW."status"::text, '')) IN (('completing', 'completed'), ('completing', 'failed'), ('failed', 'initiated'), ('initiated', 'expired'), ('initiated', 'failed'), ('initiated', 'uploading'), ('uploading', 'completing'), ('uploading', 'expired'), ('uploading', 'failed'), ('uploading', 'uploading'))
       ) THEN
        RAISE WARNING 'state_transition_not_declared: upload_sessions.status % -> %', OLD."status", NEW."status";
    END IF;
    RETURN NEW;
END $$;

DROP TRIGGER IF EXISTS upload_sessions_status_transition_check ON bucket.upload_sessions;
CREATE TRIGGER upload_sessions_status_transition_check
    BEFORE UPDATE OF "status" ON bucket.upload_sessions
    FOR EACH ROW EXECUTE FUNCTION bucket.upload_sessions_status_transition_check();
